@import "tailwindcss";

@theme {
  --font-sans: "Plus Jakarta Sans", ui-sans-serif, system-ui, -apple-system,
    "Segoe UI", sans-serif;
  --font-display: "Plus Jakarta Sans", ui-sans-serif, system-ui, sans-serif;

  --color-sunset-50: #fff7ed;
  --color-sunset-100: #ffedd5;
  --color-sunset-300: #fdba74;
  --color-sunset-400: #fb923c;
  --color-sunset-500: #f97316;
  --color-sunset-600: #ea580c;
  --color-plum-500: #8b5cf6;
  --color-plum-600: #7c3aed;
  --color-plum-700: #6d28d9;
  --color-night-800: #1e1b4b;
  --color-night-900: #17123a;

  --animate-float: float 7s ease-in-out infinite;
  --animate-float-slow: float 11s ease-in-out infinite;
  --animate-drift: drift 18s linear infinite;
  --animate-fly: fly 14s ease-in-out infinite;
  --animate-shimmer: shimmer 1.6s linear infinite;

  @keyframes float {
    0%,
    100% {
      transform: translateY(0);
    }
    50% {
      transform: translateY(-16px);
    }
  }
  @keyframes drift {
    from {
      transform: translateX(-10vw);
    }
    to {
      transform: translateX(110vw);
    }
  }
  @keyframes fly {
    0% {
      transform: translate(0, 0) rotate(-8deg);
    }
    25% {
      transform: translate(4vw, -3vh) rotate(-4deg);
    }
    50% {
      transform: translate(8vw, -1vh) rotate(-10deg);
    }
    75% {
      transform: translate(4vw, 2vh) rotate(-4deg);
    }
    100% {
      transform: translate(0, 0) rotate(-8deg);
    }
  }
  @keyframes shimmer {
    from {
      background-position: -200% 0;
    }
    to {
      background-position: 200% 0;
    }
  }
}

:root {
  --font-body:
    "Plus Jakarta Sans", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI",
    sans-serif;
  --font-display: var(--font-body);
  --font-mono:
    ui-monospace, SFMono-Regular, "SF Mono", Consolas, "Liberation Mono", monospace;

  font-family: var(--font-body);
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

html,
body,
#root {
  min-width: 320px;
  min-height: 100%;
  margin: 0;
}

button,
input,
textarea,
select {
  font: inherit;
}

:where(h1, h2, h3, h4) {
  font-family: var(--font-display);
}

:where(code, kbd, pre, samp) {
  font-family: var(--font-mono);
}

/* Reveal-on-scroll */
.reveal {
  opacity: 0;
  transform: translateY(28px);
  transition:
    opacity 0.7s ease,
    transform 0.7s cubic-bezier(0.22, 1, 0.36, 1);
}
.reveal.is-visible {
  opacity: 1;
  transform: translateY(0);
}

/* Shimmer loading button */
.btn-shimmer {
  background-image: linear-gradient(
    110deg,
    transparent 30%,
    rgba(255, 255, 255, 0.35) 50%,
    transparent 70%
  );
  background-size: 200% 100%;
  animation: shimmer 1.4s linear infinite;
}

/* Card hover lift */
.lift {
  transition:
    transform 0.35s cubic-bezier(0.22, 1, 0.36, 1),
    box-shadow 0.35s ease;
}
.lift:hover {
  transform: translateY(-6px);
  box-shadow: 0 20px 40px -18px rgb(23 18 58 / 0.35);
}

/* Gradient placeholder for failed images */
.img-fallback {
  background: linear-gradient(135deg, #f97316 0%, #8b5cf6 60%, #4c1d95 100%);
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }
  .reveal {
    opacity: 1;
    transform: none;
    transition: none;
  }
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

export type Band = "domestik-dekat" | "domestik-jauh" | "asean" | "asia" | "menengah" | "jauh";

export interface PricingBand {
  /** Estimasi tiket pesawat PP per orang (min, max) dalam Rupiah */
  flight: [number, number];
  hotel: { budget: number; mid: number; premium: number };
  /** Makan per hari per orang (min, max) */
  meals: [number, number];
  /** Transport lokal per hari (min, max) */
  localTransport: [number, number];
  label: string;
}

const BANDS: Record<Band, PricingBand> = {
  "domestik-dekat": {
    flight: [900_000, 1_800_000],
    hotel: { budget: 250_000, mid: 600_000, premium: 1_500_000 },
    meals: [80_000, 200_000],
    localTransport: [50_000, 150_000],
    label: "Domestik (dekat)",
  },
  "domestik-jauh": {
    flight: [1_800_000, 3_500_000],
    hotel: { budget: 300_000, mid: 750_000, premium: 2_000_000 },
    meals: [90_000, 220_000],
    localTransport: [60_000, 180_000],
    label: "Domestik (jauh)",
  },
  asean: {
    flight: [1_500_000, 4_000_000],
    hotel: { budget: 350_000, mid: 900_000, premium: 2_500_000 },
    meals: [120_000, 350_000],
    localTransport: [80_000, 200_000],
    label: "Asia Tenggara",
  },
  asia: {
    flight: [3_000_000, 8_000_000],
    hotel: { budget: 450_000, mid: 1_200_000, premium: 3_500_000 },
    meals: [150_000, 450_000],
    localTransport: [100_000, 250_000],
    label: "Asia Timur & Selatan",
  },
  menengah: {
    flight: [6_000_000, 10_000_000],
    hotel: { budget: 700_000, mid: 1_800_000, premium: 5_000_000 },
    meals: [250_000, 600_000],
    localTransport: [120_000, 300_000],
    label: "Timur Tengah",
  },
  jauh: {
    flight: [8_000_000, 15_000_000],
    hotel: { budget: 800_000, mid: 2_200_000, premium: 6_000_000 },
    meals: [300_000, 800_000],
    localTransport: [150_000, 400_000],
    label: "Eropa / Australia / Amerika",
  },
};

/** Kota dengan biaya hidup tinggi: naikkan kelas band hotel & makan. */
const HIGH_COST = new Set([
  "Tokyo",
  "Osaka",
  "Singapore",
  "Hong Kong",
  "Paris",
  "London",
  "Amsterdam",
  "Rome",
  "Sydney",
  "Malé",
  "Zurich",
  "Interlaken",
  "Reykjavik",
  "New York",
  "Los Angeles",
  "San Francisco",
  "Honolulu",
  "Dubai",
]);

const COUNTRY_BAND: Record<string, Band> = {
  "Indonesia": "domestik-jauh",
  "Singapore": "asean",
  "Malaysia": "asean",
  "Thailand": "asean",
  "Vietnam": "asean",
  "Cambodia": "asean",
  "Laos": "asean",
  "Philippines": "asean",
  "Myanmar": "asean",
  "Brunei": "asean",
  "Japan": "asia",
  "South Korea": "asia",
  "Hong Kong": "asia",
  "Macau": "asia",
  "Taiwan": "asia",
  "China": "asia",
  "Mongolia": "asia",
  "India": "asia",
  "Nepal": "asia",
  "Sri Lanka": "asean",
  "Maldives": "menengah",
  "Bangladesh": "asia",
  "United Arab Emirates": "menengah",
  "Qatar": "menengah",
  "Turkey": "menengah",
  "Saudi Arabia": "menengah",
  "Jordan": "menengah",
  "Oman": "menengah",
};

const NEAR_DOMESTIC_PAIRS = [
  ["jakarta", "bandung"],
  ["jakarta", "bogor"],
  ["jakarta", "tangerang"],
  ["surabaya", "malang"],
  ["surabaya", "bromo (probolinggo)"],
  ["yogyakarta", "solo"],
  ["yogyakarta", "semarang"],
  ["denpasar (bali)", "lombok"],
  ["medan", "aceh (banda aceh)"],
];

export function getBand(cityName: string, country: string, originName: string): Band {
  if (country === "Indonesia") {
    const a = originName.toLowerCase();
    const b = cityName.toLowerCase();
    if (
      NEAR_DOMESTIC_PAIRS.some(
        ([x, y]) => (a === x && b === y) || (a === y && b === x),
      )
    ) {
      return "domestik-dekat";
    }
    return "domestik-jauh";
  }
  return COUNTRY_BAND[country] ?? "jauh";
}

export function getPricing(cityName: string, country: string, originName: string): PricingBand {
  const band = getBand(cityName, country, originName);
  const base = BANDS[band];
  if (HIGH_COST.has(cityName)) {
    return {
      ...base,
      hotel: {
        budget: Math.round(base.hotel.budget * 1.5),
        mid: Math.round(base.hotel.mid * 1.5),
        premium: Math.round(base.hotel.premium * 1.5),
      },
      meals: [Math.round(base.meals[0] * 1.4), Math.round(base.meals[1] * 1.4)],
      localTransport: [
        Math.round(base.localTransport[0] * 1.2),
        Math.round(base.localTransport[1] * 1.2),
      ],
    };
  }
  return base;
}

/** Opsi transportasi darat/laut untuk rute domestik dekat. */
export function groundOption(band: Band): { label: string; price: [number, number] } | undefined {
  if (band !== "domestik-dekat") return undefined;
  return { label: "Kereta / travel antar kota (PP)", price: [200_000, 600_000] };
}

function hashStr(str: string): number {
  let h = 2166136261;
  for (let i = 0; i < str.length; i++) h = (h ^ str.charCodeAt(i)) * 16777619 >>> 0;
  return h;
}

/** Jitter deterministik 0.94–1.10 agar angka terlihat realistis namun stabil. */
export function jitter(seed: string, base: number): number {
  const h = hashStr(seed);
  const factor = 0.94 + ((h % 1000) / 1000) * 0.16;
  return Math.round((base * factor) / 1000) * 1000;
}

export function formatIDR(n: number): string {
  return new Intl.NumberFormat("id-ID", {
    style: "currency",
    currency: "IDR",
    maximumFractionDigits: 0,
  }).format(n);
}

export function toISODate(d: Date): string {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}

export function parseISO(iso: string): Date {
  const [y, m, d] = iso.split("-").map(Number);
  return new Date(y, m - 1, d);
}

export function addDays(d: Date, n: number): Date {
  const copy = new Date(d);
  copy.setDate(copy.getDate() + n);
  return copy;
}

export function diffDays(a: Date, b: Date): number {
  return Math.round((b.getTime() - a.getTime()) / 86_400_000);
}

export function isWeekend(d: Date): boolean {
  const day = d.getDay();
  return day === 0 || day === 6;
}

const fmtLong = new Intl.DateTimeFormat("id-ID", {
  weekday: "long",
  day: "numeric",
  month: "long",
  year: "numeric",
});

const fmtShort = new Intl.DateTimeFormat("id-ID", {
  day: "numeric",
  month: "short",
});

const fmtShortYear = new Intl.DateTimeFormat("id-ID", {
  day: "numeric",
  month: "short",
  year: "numeric",
});

const fmtDay = new Intl.DateTimeFormat("id-ID", {
  weekday: "short",
});

export function formatLong(d: Date): string {
  return fmtLong.format(d);
}

export function formatShort(d: Date): string {
  return fmtShort.format(d);
}

export function formatShortYear(d: Date): string {
  return fmtShortYear.format(d);
}

export function formatDayName(d: Date): string {
  return fmtDay.format(d);
}

export function formatRange(start: Date, end: Date): string {
  if (start.getFullYear() !== end.getFullYear()) {
    return `${formatShortYear(start)} – ${formatShortYear(end)}`;
  }
  if (start.getMonth() !== end.getMonth()) {
    return `${formatShort(start)} – ${formatShortYear(end)}`;
  }
  if (start.getDate() === end.getDate()) return formatShortYear(start);
  return `${start.getDate()} – ${formatShortYear(end)}`;
}

import type { City } from "#/data/cities";
import type { DestinationProfile } from "#/data/destinations";
import { getProfile } from "#/data/destinations";
import { HOLIDAYS, holidayOn } from "#/data/holidays";
import {
  getBand,
  getPricing,
  groundOption,
  jitter,
} from "#/data/pricing";
import { addDays, diffDays, isWeekend, parseISO, toISODate } from "#/lib/dateUtils";

const holidayDates = new Set(HOLIDAYS.map((h) => h.date));

// ---------------------------------------------------------------------------
// Date suggestions
// ---------------------------------------------------------------------------

export interface DateOption {
  id: "pilihan" | "optimal-1" | "optimal-2";
  start: Date;
  end: Date;
  /** Hari libur gratis (Sabtu/Minggu/tanggal merah) yang ikut dalam rentang */
  freeDays: number;
  totalDaysOff: number;
  leaveDaysUsed: number;
  holidaysCovered: { date: string; name: string }[];
  reason: string;
  score: number;
  isUserChoice: boolean;
}

interface Window {
  start: Date;
  end: Date;
  leave: number;
  total: number;
  holidays: { date: string; name: string }[];
}

function analyzeWindow(start: Date, leaveDays: number): Window {
  const end = addDays(start, leaveDays - 1);
  let leave = 0;
  const holidays: { date: string; name: string }[] = [];
  for (let i = 0; i < leaveDays; i++) {
    const d = addDays(start, i);
    const iso = toISODate(d);
    const h = holidayOn(iso);
    if (h) holidays.push({ date: iso, name: h.name });
    if (!isWeekend(d) && !holidayDates.has(iso)) leave++;
  }
  return { start, end, leave, total: leaveDays, holidays };
}

/**
 * Perluas rentang ke kiri/kanan menelan weekend & tanggal merah yang berdempetan,
 * sehingga total hari libur > hari cuti yang dipakai.
 */
function bridgeWindow(start: Date, leaveDays: number): Window {
  let s = start;
  let e = addDays(start, leaveDays - 1);
  const isFree = (d: Date) => isWeekend(d) || holidayDates.has(toISODate(d));
  while (isFree(addDays(s, -1))) s = addDays(s, -1);
  while (isFree(addDays(e, 1))) e = addDays(e, 1);
  const w = analyzeWindow(s, diffDays(s, e) + 1);
  return w;
}

function windowScore(w: Window, leaveDaysRequested: number): number {
  const freeDays = w.total - w.leave;
  const efficiency = w.leave === 0 ? w.total * 2 : w.total / w.leave;
  // Penalti bila cuti yang dipakai jauh melebihi permintaan
  const overuse = Math.max(0, w.leave - leaveDaysRequested);
  return efficiency * 10 + freeDays * 2 + w.holidays.length * 1.5 - overuse * 8;
}

function reasonFor(w: Window, leaveDaysRequested: number): string {
  const freeDays = w.total - w.leave;
  const names = w.holidays.map((h) => h.name);
  const holidayPhrase =
    names.length > 0
      ? ` ${names.length > 1 ? "Menyambung rangkaian" : "Menempel"} ${names[0]}${names.length > 1 ? " dan tanggal merah lainnya" : ""}.`
      : " Menyambung akhir pekan.";
  const harpitnas = freeDays >= 3 && w.leave <= Math.max(2, leaveDaysRequested - 1);
  const base = harpitnas
    ? "Strategi harpitnas maksimal: ambil cuti di hari yang terjepit."
    : names.length > 0
      ? "Memanfaatkan tanggal merah agar cuti lebih panjang."
      : "Mengapit akhir pekan sehingga hari kerja yang dipakai minimal.";
  return `${base}${holidayPhrase} Total ${w.total} hari libur cukup dengan ${w.leave} hari cuti.`;
}

export function suggestDates(leaveDays: number, preferredStart: Date): DateOption[] {
  const user = bridgeWindow(preferredStart, leaveDays);
  const options: DateOption[] = [
    {
      id: "pilihan",
      start: user.start,
      end: user.end,
      freeDays: user.total - user.leave,
      totalDaysOff: user.total,
      leaveDaysUsed: user.leave,
      holidaysCovered: user.holidays,
      reason:
        user.holidays.length > 0 || user.total - user.leave > 2
          ? `Pilihanmu sudah lumayan: rentang ini menyentuh ${user.holidays.length > 0 ? `${user.holidays[0].name} dan ` : ""}akhir pekan. Total ${user.total} hari libur dengan ${user.leave} hari cuti.`
          : `Tanggal pilihanmu sendiri — ${user.total} hari penuh dengan ${user.leave} hari cuti, tanpa bonus tanggal merah.`,
      score: windowScore(user, leaveDays),
      isUserChoice: true,
    },
  ];

  // Pindai window kandidat di sekitar tanggal pilihan (±35 hari)
  const seen = new Set<string>([toISODate(user.start)]);
  const candidates: Window[] = [];
  for (let offset = -35; offset <= 35; offset++) {
    if (offset === 0) continue;
    const w = bridgeWindow(addDays(preferredStart, offset), leaveDays);
    const key = toISODate(w.start);
    if (seen.has(key)) continue;
    seen.add(key);
    // Hanya kandidat yang benar-benar punya bonus (tanggal merah atau jembatan panjang)
    const bonus = w.total - w.leave - countWeekendsIn(w.start, leaveDays);
    if (w.holidays.length === 0 && bonus <= 0 && w.total - w.leave <= 2) continue;
    candidates.push(w);
  }
  candidates.sort((a, b) => windowScore(b, leaveDays) - windowScore(a, leaveDays));

  for (const w of candidates.slice(0, 2)) {
    options.push({
      id: options.length === 1 ? "optimal-1" : "optimal-2",
      start: w.start,
      end: w.end,
      freeDays: w.total - w.leave,
      totalDaysOff: w.total,
      leaveDaysUsed: w.leave,
      holidaysCovered: w.holidays,
      reason: reasonFor(w, leaveDays),
      score: windowScore(w, leaveDays),
      isUserChoice: false,
    });
  }

  // Tandai skor tertinggi; jika pilihan user menang, tukar urutan tetap tapi badge ikut skor
  return options.slice(0, 3);
}

function countWeekendsIn(start: Date, days: number): number {
  let n = 0;
  for (let i = 0; i < days; i++) if (isWeekend(addDays(start, i))) n++;
  return n;
}

// ---------------------------------------------------------------------------
// Itinerary
// ---------------------------------------------------------------------------

export interface Activity {
  time: "Pagi" | "Siang" | "Sore" | "Malam";
  title: string;
  detail: string;
  ticket: number;
}

export interface ItineraryDay {
  day: number;
  date: Date;
  activities: Activity[];
  photos: { url: string; alt: string }[];
}

function pick<T>(arr: T[], index: number): T {
  return arr[index % arr.length];
}

export function buildItinerary(
  start: Date,
  days: number,
  profile: DestinationProfile,
  originName: string,
): ItineraryDay[] {
  const result: ItineraryDay[] = [];
  let attractionIdx = 0;
  let foodIdx = 0;

  for (let i = 0; i < days; i++) {
    const date = addDays(start, i);
    const photos = [pick(profile.photos, i), pick(profile.photos, i + 1)];
    const activities: Activity[] = [];
    const nextAttraction = () => {
      const a = profile.attractions[attractionIdx % profile.attractions.length];
      attractionIdx++;
      return a;
    };
    const nextFood = () => {
      const f = profile.foods[foodIdx % profile.foods.length];
      foodIdx++;
      return f;
    };

    if (i === 0) {
      const a1 = nextAttraction();
      const f = nextFood();
      activities.push(
        {
          time: "Pagi",
          title: `Berangkat dari ${originName}`,
          detail: "Check-in lebih awal, siapkan dokumen perjalanan, dan sarapan sebelum berangkat.",
          ticket: 0,
        },
        {
          time: "Siang",
          title: `Tiba di ${profile.city} & check-in hotel`,
          detail: "Istirahat sebentar lalu mulai eksplorasi area sekitar penginapan.",
          ticket: 0,
        },
        {
          time: "Sore",
          title: a1.name,
          detail: a1.desc,
          ticket: a1.ticket,
        },
        {
          time: "Malam",
          title: `Makan malam: ${f.name}`,
          detail: `Kuliner khas wajib coba (${f.priceRange}). Lalu istirahat untuk hari penuh besok.`,
          ticket: 0,
        },
      );
    } else if (i === days - 1 && days > 1) {
      const f = nextFood();
      activities.push(
        {
          time: "Pagi",
          title: "Sarapan santai & packing",
          detail: "Nikmati pagi terakhir, check-out hotel, titip koper bila perlu.",
          ticket: 0,
        },
        {
          time: "Siang",
          title: "Belanja oleh-oleh",
          detail: `Mampir ke ${nextAttraction().name} atau pusat oleh-oleh khas ${profile.city}.`,
          ticket: 0,
        },
        {
          time: "Sore",
          title: `Kembali ke ${originName}`,
          detail: "Menuju bandara/terminal lebih awal untuk antisipasi antrean.",
          ticket: 0,
        },
        {
          time: "Malam",
          title: `Tiba di ${originName}`,
          detail: `Perjalanan selesai — sempurna ditutup dengan ${f.name} jika masih sempat.`,
          ticket: 0,
        },
      );
    } else {
      const a1 = nextAttraction();
      const a2 = nextAttraction();
      const a3 = nextAttraction();
      const f = nextFood();
      activities.push(
        {
          time: "Pagi",
          title: a1.name,
          detail: `${a1.desc} Datang pagi agar lebih sepi.`,
          ticket: a1.ticket,
        },
        {
          time: "Siang",
          title: a2.name,
          detail: `${a2.desc} Makan siang: coba ${f.name} (${f.priceRange}).`,
          ticket: a2.ticket,
        },
        {
          time: "Sore",
          title: a3.name,
          detail: a3.desc,
          ticket: a3.ticket,
        },
        {
          time: "Malam",
          title: "Santai & jelajah malam",
          detail: `Kembali ke hotel atau nikmati suasana malam ${profile.city} di sekitar penginapan.`,
          ticket: 0,
        },
      );
    }

    result.push({ day: i + 1, date, activities, photos });
  }
  return result;
}

// ---------------------------------------------------------------------------
// Budget
// ---------------------------------------------------------------------------

export type HotelTier = "budget" | "mid" | "premium";

export interface BudgetBreakdown {
  flightLabel: string;
  flight: [number, number];
  ground?: { label: string; price: [number, number] };
  hotelPerNight: Record<HotelTier, number>;
  nights: number;
  meals: [number, number];
  localTransport: [number, number];
  attractionTickets: number;
  bufferRate: number;
  total: (tier: HotelTier) => { min: number; max: number };
  rows: (tier: HotelTier) => { label: string; min: number; max: number }[];
}

export function estimateBudget(
  origin: City,
  destinationName: string,
  destinationCountry: string,
  start: Date,
  days: number,
  itinerary: ItineraryDay[],
): BudgetBreakdown {
  const pricing = getPricing(destinationName, destinationCountry, origin.name);
  const band = getBand(destinationName, destinationCountry, origin.name);
  const seed = `${origin.name}->${destinationName}`;
  const nights = Math.max(0, days - 1);

  const flight: [number, number] = [
    jitter(seed + "f0", pricing.flight[0]),
    jitter(seed + "f1", pricing.flight[1]),
  ];
  const ground = groundOption(band);
  const groundJittered = ground
    ? { label: ground.label, price: [jitter(seed + "g0", ground.price[0]), jitter(seed + "g1", ground.price[1])] as [number, number] }
    : undefined;

  const meals: [number, number] = [
    jitter(seed + "m0", pricing.meals[0] * days),
    jitter(seed + "m1", pricing.meals[1] * days),
  ];
  const localTransport: [number, number] = [
    jitter(seed + "t0", pricing.localTransport[0] * days),
    jitter(seed + "t1", pricing.localTransport[1] * days),
  ];
  const attractionTickets = itinerary.reduce(
    (sum, d) => sum + d.activities.reduce((s, a) => s + a.ticket, 0),
    0,
  );

  const hotelPerNight: Record<HotelTier, number> = {
    budget: jitter(seed + "hb", pricing.hotel.budget),
    mid: jitter(seed + "hm", pricing.hotel.mid),
    premium: jitter(seed + "hp", pricing.hotel.premium),
  };

  const bufferRate = 0.1;
  const hotelCost = (tier: HotelTier) => hotelPerNight[tier] * nights;

  const total = (tier: HotelTier) => {
    const min = Math.round((flight[0] + hotelCost(tier) + meals[0] + localTransport[0] + attractionTickets) * (1 + bufferRate));
    const max = Math.round((flight[1] + hotelCost(tier) + meals[1] + localTransport[1] + attractionTickets) * (1 + bufferRate));
    return { min, max };
  };

  const rows = (tier: HotelTier) => {
    const hc = hotelCost(tier);
    const base: { label: string; min: number; max: number }[] = [
      { label: `Transport PP — ${flight[0] > 0 ? "pesawat" : "transport"} (${origin.name} ⇄ ${destinationName})`, min: flight[0], max: flight[1] },
      { label: `Hotel ${tierLabel(tier)} — ${nights} malam`, min: hc, max: hc },
      { label: `Makan — ${days} hari`, min: meals[0], max: meals[1] },
      { label: "Transport lokal", min: localTransport[0], max: localTransport[1] },
      { label: "Tiket atraksi (sesuai itinerary)", min: attractionTickets, max: attractionTickets },
    ];
    const subMin = base.reduce((s, r) => s + r.min, 0);
    const subMax = base.reduce((s, r) => s + r.max, 0);
    base.push({
      label: "Dana darurat (10%)",
      min: Math.round(subMin * bufferRate),
      max: Math.round(subMax * bufferRate),
    });
    return base;
  };

  return {
    flightLabel: "Pesawat PP (estimasi OTA)",
    flight,
    ground: groundJittered,
    hotelPerNight,
    nights,
    meals,
    localTransport,
    attractionTickets,
    bufferRate,
    total,
    rows,
  };
}

export function tierLabel(tier: HotelTier): string {
  return tier === "budget" ? "Budget ★★" : tier === "mid" ? "Mid-range ★★★" : "Premium ★★★★+";
}

// ---------------------------------------------------------------------------
// Combined plan
// ---------------------------------------------------------------------------

export interface TripInput {
  days: number;
  startDate: Date;
  origin: City;
  destination: string; // nama kota (bisa dari autocomplete atau bebas)
  destinationCountry: string;
}

export interface TripPlan {
  input: TripInput;
  options: DateOption[];
  profile: DestinationProfile;
}

export function createPlan(input: TripInput): TripPlan {
  return {
    input,
    options: suggestDates(input.days, input.startDate),
    profile: getProfile(input.destination),
  };
}

export function itineraryFor(plan: TripPlan, option: DateOption): ItineraryDay[] {
  const start = option.isUserChoice ? plan.input.startDate : option.start;
  // Untuk window hasil bridging, itinerary dimulai dari awal rentang libur
  return buildItinerary(start, plan.input.days, plan.profile, plan.input.origin.name);
}

export function budgetFor(plan: TripPlan, option: DateOption): BudgetBreakdown {
  const it = itineraryFor(plan, option);
  return estimateBudget(
    plan.input.origin,
    plan.input.destination,
    plan.input.destinationCountry,
    option.start,
    plan.input.days,
    it,
  );
}

/** Alias agar tidak ada unused import */
export { parseISO };

export interface SavedPlan {
  id: string;
  label: string;
  createdAt: string;
  payload: {
    days: number;
    startDate: string; // ISO
    origin: string;
    destination: string;
    destinationCountry: string;
  };
}

const KEY = "cutiku.plans.v1";

export function loadPlans(): SavedPlan[] {
  try {
    const raw = localStorage.getItem(KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw) as SavedPlan[];
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

export function savePlan(plan: Omit<SavedPlan, "id" | "createdAt">): SavedPlan[] {
  const plans = loadPlans();
  const entry: SavedPlan = {
    ...plan,
    id: `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
    createdAt: new Date().toISOString(),
  };
  const next = [entry, ...plans].slice(0, 12);
  try {
    localStorage.setItem(KEY, JSON.stringify(next));
  } catch {
    // storage penuh / tidak tersedia — abaikan
  }
  return next;
}

export function deletePlan(id: string): SavedPlan[] {
  const next = loadPlans().filter((p) => p.id !== id);
  try {
    localStorage.setItem(KEY, JSON.stringify(next));
  } catch {
    // abaikan
  }
  return next;
}

import { useEffect, useRef, useState } from "react";

/** Menambahkan kelas .is-visible saat elemen masuk viewport. */
export function useReveal<T extends HTMLElement>() {
  const ref = useRef<T | null>(null);
  const [visible, setVisible] = useState(false);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    if (typeof IntersectionObserver === "undefined") {
      setVisible(true);
      return;
    }
    const io = new IntersectionObserver(
      (entries) => {
        for (const e of entries) {
          if (e.isIntersecting) {
            setVisible(true);
            io.disconnect();
          }
        }
      },
      { threshold: 0.12 },
    );
    io.observe(el);
    return () => io.disconnect();
  }, []);

  return { ref, className: `reveal${visible ? " is-visible" : ""}` };
}

