   302	export interface BudgetBreakdown {
   303	  flightLabel: string;
   304	  flight: [number, number];
   305	  ground?: { label: string; price: [number, number] };
   306	  hotelPerNight: Record<HotelTier, number>;
   307	  nights: number;
   308	  meals: [number, number];
   309	  localTransport: [number, number];
   310	  attractionTickets: number;
   311	  bufferRate: number;
   312	  total: (tier: HotelTier) => { min: number; max: number };
   313	  rows: (tier: HotelTier) => { label: string; min: number; max: number }[];
   314	}
   315	
   316	export function estimateBudget(
   317	  origin: City,
   318	  destinationName: string,
   319	  destinationCountry: string,
   320	  days: number,
   321	  itinerary: ItineraryDay[],
   322	): BudgetBreakdown {
   323	  const pricing = getPricing(destinationName, destinationCountry, origin.name);
   324	  const band = getBand(destinationName, destinationCountry, origin.name);
   325	  const seed = `${origin.name}->${destinationName}`;
   326	  const nights = Math.max(0, days - 1);
   327	
   328	  const flight: [number, number] = [
   329	    jitter(seed + "f0", pricing.flight[0]),
   330	    jitter(seed + "f1", pricing.flight[1]),
   331	  ];
   332	  const ground = groundOption(band);
   333	  const groundJittered = ground
   334	    ? { label: ground.label, price: [jitter(seed + "g0", ground.price[0]), jitter(seed + "g1", ground.price[1])] as [number, number] }
   335	    : undefined;
   336	
   337	  const meals: [number, number] = [
   338	    jitter(seed + "m0", pricing.meals[0] * days),
   339	    jitter(seed + "m1", pricing.meals[1] * days),
   340	  ];
   341	  const localTransport: [number, number] = [
   342	    jitter(seed + "t0", pricing.localTransport[0] * days),
   343	    jitter(seed + "t1", pricing.localTransport[1] * days),
   344	  ];
   345	  const attractionTickets = itinerary.reduce(
   346	    (sum, d) => sum + d.activities.reduce((s, a) => s + a.ticket, 0),
   347	    0,
   348	  );
   349	
   350	  const hotelPerNight: Record<HotelTier, number> = {
   351	    budget: jitter(seed + "hb", pricing.hotel.budget),
   352	    mid: jitter(seed + "hm", pricing.hotel.mid),
   353	    premium: jitter(seed + "hp", pricing.hotel.premium),
   354	  };
   355	
   356	  const bufferRate = 0.1;
   357	  const hotelCost = (tier: HotelTier) => hotelPerNight[tier] * nights;
   358	
   359	  const total = (tier: HotelTier) => {
   360	    const min = Math.round((flight[0] + hotelCost(tier) + meals[0] + localTransport[0] + attractionTickets) * (1 + bufferRate));
   361	    const max = Math.round((flight[1] + hotelCost(tier) + meals[1] + localTransport[1] + attractionTickets) * (1 + bufferRate));
   362	    return { min, max };
   363	  };
   364	
   365	  const rows = (tier: HotelTier) => {
   366	    const hc = hotelCost(tier);
   367	    const base: { label: string; min: number; max: number }[] = [
   368	      { label: `Transport PP — ${flight[0] > 0 ? "pesawat" : "transport"} (${origin.name} ⇄ ${destinationName})`, min: flight[0], max: flight[1] },
   369	      { label: `Hotel ${tierLabel(tier)} — ${nights} malam`, min: hc, max: hc },
   370	      { label: `Makan — ${days} hari`, min: meals[0], max: meals[1] },
   371	      { label: "Transport lokal", min: localTransport[0], max: localTransport[1] },
   372	      { label: "Tiket atraksi (sesuai itinerary)", min: attractionTickets, max: attractionTickets },
   373	    ];
   374	    const subMin = base.reduce((s, r) => s + r.min, 0);
   375	    const subMax = base.reduce((s, r) => s + r.max, 0);
   376	    base.push({
   377	      label: "Dana darurat (10%)",
   378	      min: Math.round(subMin * bufferRate),
   379	      max: Math.round(subMax * bufferRate),
   380	    });
   381	    return base;
   382	  };
   383	
   384	  return {
   385	    flightLabel: "Pesawat PP (estimasi OTA)",
   386	    flight,
   387	    ground: groundJittered,
   388	    hotelPerNight,
   389	    nights,
   390	    meals,
   391	    localTransport,
   392	    attractionTickets,
   393	    bufferRate,
   394	    total,
   395	    rows,
   396	  };
   397	}
