   173	/** Jitter deterministik 0.94–1.10 agar angka terlihat realistis namun stabil. */
   174	export function jitter(seed: string, base: number): number {
   175	  const h = hashStr(seed);
   176	  const factor = 0.94 + ((h % 1000) / 1000) * 0.16;
   177	  return Math.round((base * factor) / 1000) * 1000;
   178	}
