    15	function useAnimatedNumber(target: number): number {
    16	  const [value, setValue] = useState(target);
    17	  const prev = useRef(target);
    18	
    19	  useEffect(() => {
    20	    const from = prev.current;
    21	    if (from === target) return;
    22	    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    23	    if (reduced) {
    24	      prev.current = target;
    25	      setValue(target);
    26	      return;
    27	    }
    28	    const startTime = performance.now();
    29	    const dur = 600;
    30	    let raf = 0;
    31	    const step = (now: number) => {
    32	      const t = Math.min(1, (now - startTime) / dur);
    33	      const eased = 1 - Math.pow(1 - t, 3);
    34	      setValue(Math.round(from + (target - from) * eased));
    35	      if (t < 1) raf = requestAnimationFrame(step);
    36	      else prev.current = target;
    37	    };
    38	    raf = requestAnimationFrame(step);
    39	    return () => cancelAnimationFrame(raf);
    40	  }, [target]);
    41	
    42	  return value;
    43	}
