  setStops((s) => {
    const idx = s.findIndex((st) => st.key === key);
    const target = idx + dir;
    if (idx < 0 || target < 0 || target >= s.length) return s;
    const next = [...s];
    [next[idx], next[target]] = [next[target], next[idx]];
    return next;
  });
};

