import { Loader } from "@googlemaps/js-api-loader";

/** API key dari env build (Vite). Kosong = fitur Google Places nonaktif, fallback lokal. */
const API_KEY: string = (import.meta.env.VITE_GOOGLE_MAPS_API_KEY as string | undefined) ?? "";

export const placesEnabled = API_KEY.length > 0;

export interface PlaceSuggestion {
  /** Nama utama tempat (mis. "Gili Trawangan") */
  mainText: string;
  /** Wilayah/negara (mis. "Kepulauan Gili, Lombok, Indonesia") */
  secondaryText: string;
  /** Negara ISO/code bila tersedia dari terms */
  country: string;
  placeId: string;
}

export interface PlaceDetails {
  name: string;
  country: string;
  countryCode: string;
  photoUrls: string[];
}

// ---------------------------------------------------------------------------
// Loader & service singletons
// ---------------------------------------------------------------------------

let loaderPromise: Promise<typeof google> | null = null;

function loadGoogle(): Promise<typeof google> {
  if (!loaderPromise) {
    loaderPromise = new Loader({ apiKey: API_KEY, version: "weekly", language: "id" })
      .importLibrary("places")
      .then(() => google);
  }
  return loaderPromise;
}

// ---------------------------------------------------------------------------
// Autocomplete (legacy AutocompleteService — kompatibel semua API key)
// ---------------------------------------------------------------------------

const GEOCODE_TYPES = ["(cities)", "locality", "sublocality", "establishment", "tourist_attraction"];

export async function fetchPlaceSuggestions(query: string): Promise<PlaceSuggestion[]> {
  if (!placesEnabled || query.trim().length < 2) return [];
  try {
    await loadGoogle();
    const service = new google.maps.places.AutocompleteService();
    const predictions = await new Promise<google.maps.places.AutocompletePrediction[]>(
      (resolve, reject) => {
        service.getPlacePredictions(
          { input: query, types: GEOCODE_TYPES, language: "id" },
          (results, status) => {
            if (
              status === google.maps.places.PlacesServiceStatus.OK ||
              status === google.maps.places.PlacesServiceStatus.ZERO_RESULTS
            ) {
              resolve(results ?? []);
            } else {
              reject(new Error(`Places status: ${status}`));
            }
          },
        );
      },
    );
    return predictions.slice(0, 6).map((p) => {
      const sf = p.structured_formatting;
      const countryTerm = p.terms[p.terms.length - 1]?.value ?? "";
      const lastSecondary = sf.secondary_text?.split(",").pop()?.trim() ?? "";
      return {
        mainText: sf.main_text || p.description.split(",")[0],
        secondaryText: sf.secondary_text ?? "",
        // Hindari duplikasi nama di secondary (mis. nama sama dengan negara)
        country: lastSecondary && lastSecondary.toLowerCase() !== (sf.main_text ?? "").toLowerCase()
          ? lastSecondary
          : countryTerm,
        placeId: p.place_id,
      };
    });
  } catch {
    return [];
  }
}

// ---------------------------------------------------------------------------
// Place details (nama kanonik, negara, foto)
// ---------------------------------------------------------------------------

let detailsSession: { service: google.maps.places.PlacesService } | null = null;

function getDetailsService(): google.maps.places.PlacesService {
  if (!detailsSession) {
    const node = document.createElement("div");
    detailsSession = { service: new google.maps.places.PlacesService(node) };
  }
  return detailsSession.service;
}

export async function fetchPlaceDetails(placeId: string): Promise<PlaceDetails | null> {
  if (!placesEnabled) return null;
  try {
    await loadGoogle();
    const { service } = getDetailsService();
    const place = await new Promise<google.maps.places.PlaceResult | null>((resolve) => {
      service.getDetails(
        {
          placeId,
          fields: ["name", "address_components", "photos"],
          language: "id",
        },
        (result, status) => {
          resolve(status === google.maps.places.PlacesServiceStatus.OK ? result : null);
        },
      );
    });
    if (!place) return null;

    const countryComp = place.address_components?.find((c) => c.types.includes("country"));
    const photoUrls = (place.photos ?? [])
      .slice(0, 3)
      .map((ph) => ph.getUrl({ maxWidth: 900, maxHeight: 600 }));

    return {
      name: place.name ?? "",
      country: countryComp?.long_name ?? "",
      countryCode: countryComp?.short_name ?? "",
      photoUrls,
    };
  } catch {
    return null;
  }
}

// ---------------------------------------------------------------------------
// Enrichment cache (client-side, per sesi)
// ---------------------------------------------------------------------------

export interface EnrichedCity {
  country: string;
  photoUrls: string[];
}

const enrichCache = new Map<string, EnrichedCity>();

export function getEnriched(cityName: string): EnrichedCity | undefined {
  return enrichCache.get(cityName.trim().toLowerCase());
}

export async function enrichPlace(placeId: string, fallbackName: string): Promise<EnrichedCity> {
  const cached = getEnriched(fallbackName);
  if (cached) return cached;
  const details = await fetchPlaceDetails(placeId);
  const enriched: EnrichedCity = {
    country: details?.country || "",
    photoUrls: details?.photoUrls ?? [],
  };
  enrichCache.set((details?.name || fallbackName).trim().toLowerCase(), enriched);
  enrichCache.set(fallbackName.trim().toLowerCase(), enriched);
  return enriched;
}

import { searchCities, type City } from "#/data/cities";
import { fetchPlaceSuggestions, placesEnabled, type PlaceSuggestion } from "#/lib/places";
import { Globe, Loader2, MapPin, PencilLine } from "lucide-react";
import { useEffect, useId, useRef, useState } from "react";

interface Props {
  id: string;
  label: string;
  value: string;
  onChange: (value: string, city?: City, place?: PlaceSuggestion) => void;
  placeholder?: string;
  invalid?: boolean;
}

type Item =
  | { kind: "free" }
  | { kind: "local"; city: City }
  | { kind: "google"; place: PlaceSuggestion };

export default function CityAutocomplete({ id, label, value, onChange, placeholder, invalid }: Props) {
  const [open, setOpen] = useState(false);
  const [highlight, setHighlight] = useState(0);
  const [options, setOptions] = useState<City[]>([]);
  const [googleOptions, setGoogleOptions] = useState<PlaceSuggestion[]>([]);
  const [googleLoading, setGoogleLoading] = useState(false);
  const rootRef = useRef<HTMLDivElement>(null);
  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const listId = useId();

  const trimmed = value.trim();
  const exactMatch = options.some((ct) => ct.name.toLowerCase() === trimmed.toLowerCase());
  // Entri bebas: teks non-kosong yang tidak persis cocok dengan daftar lokal
  const freeTextOption = trimmed.length > 0 && !exactMatch;

  // Daftar lokal: instan
  useEffect(() => {
    setOptions(searchCities(value));
    setHighlight(0);
  }, [value]);

  // Google Places: debounce 300ms, minimum 2 karakter
  useEffect(() => {
    if (!placesEnabled) return;
    if (debounceRef.current) clearTimeout(debounceRef.current);
    const q = value.trim();
    if (q.length < 2) {
      setGoogleOptions([]);
      setGoogleLoading(false);
      return;
    }
    setGoogleLoading(true);
    debounceRef.current = setTimeout(() => {
      fetchPlaceSuggestions(q)
        .then((results) => {
          // Dedup berdasarkan nama terhadap daftar lokal
          const localNames = new Set(searchCities(q).map((ct) => ct.name.toLowerCase()));
          const seen = new Set<string>();
          setGoogleOptions(
            results.filter((r) => {
              const key = r.mainText.toLowerCase();
              if (localNames.has(key) || seen.has(key)) return false;
              seen.add(key);
              return true;
            }),
          );
        })
        .catch(() => setGoogleOptions([]))
        .finally(() => setGoogleLoading(false));
    }, 300);
    return () => {
      if (debounceRef.current) clearTimeout(debounceRef.current);
    };
  }, [value]);

  useEffect(() => {
    const onDoc = (e: MouseEvent) => {
      if (rootRef.current && !rootRef.current.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener("mousedown", onDoc);
    return () => document.removeEventListener("mousedown", onDoc);
  }, []);

  const select = (city: City) => {
    onChange(city.name, city, undefined);
    setOpen(false);
  };

  const selectPlace = (place: PlaceSuggestion) => {
    onChange(place.mainText, undefined, place);
    setOpen(false);
  };

  const selectFreeText = () => {
    if (trimmed) onChange(trimmed, undefined, undefined);
    setOpen(false);
  };

  const items: Item[] = [
    ...(freeTextOption ? [{ kind: "free" } as Item] : []),
    ...options.map((city): Item => ({ kind: "local", city })),
    ...googleOptions.map((place): Item => ({ kind: "google", place })),
  ];

  const onKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (!open && (e.key === "ArrowDown" || e.key === "ArrowUp")) {
      setOpen(true);
      return;
    }
    if (e.key === "ArrowDown") {
      e.preventDefault();
      setHighlight((h) => Math.min(h + 1, items.length - 1));
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      setHighlight((h) => Math.max(h - 1, 0));
    } else if (e.key === "Enter") {
      const item = open ? items[highlight] : undefined;
      if (item) {
        e.preventDefault();
        if (item.kind === "free") selectFreeText();
        else if (item.kind === "local") select(item.city);
        else selectPlace(item.place);
      }
      // Enter dengan dropdown tertutup: entri bebas diterima apa adanya
    } else if (e.key === "Escape") {
      setOpen(false);
    }
  };

  const showDropdown = open && (items.length > 0 || googleLoading);
  const showGoogleAttribution = placesEnabled && (googleOptions.length > 0 || googleLoading);

  return (
    <div ref={rootRef} className="relative">
      <label htmlFor={id} className="mb-1.5 block text-sm font-bold text-night-800">
        {label}
      </label>
      <div className="relative">
        <MapPin
          className={`pointer-events-none absolute top-1/2 left-3.5 size-4.5 -translate-y-1/2 ${
            invalid ? "text-red-500" : "text-plum-500"
          }`}
          aria-hidden
        />
        <input
          id={id}
          type="text"
