/** Profil untuk satu kota input: daftar lokal → profil spesifik (nama/negara/foto Google bila ada). */
function profileFor(name: string, country: string): DestinationProfile {
  const profile = getProfile(name);
  if (profile.city !== name) return profile; // hit dari daftar lokal
  const enriched = getEnriched(name);
  return buildSpecificProfile(name, country, enriched?.photoUrls);
}

export function createPlan(input: TripInput): TripPlan {
  const plan: TripPlan = {
    input,
    options: suggestDates(input.days, input.startDate),
    profile: profileFor(input.destination, input.destinationCountry),
  };
  if (input.route && input.route.length > 1) {
    plan.profiles = input.route.map((r) => profileFor(r.name, r.country));
    plan.allocations = allocateDays(input.days, input.route.length);
  }
  return plan;
}

