import { findCity, type City } from "#/data/cities";
import { guessCountry } from "#/data/pricing";
import type { PlaceSuggestion } from "#/lib/places";

export function resolveStop(
  text: string,
  city: City | undefined,
  place?: PlaceSuggestion,
): RouteStop {
  const resolved = city && sameCity(city.name, text) ? city : findCity(text);
  const googleCountry =
    place && sameCity(place.mainText, text) && place.country ? place.country : undefined;
  return {
    key: `${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
    name: text.trim(),
    // Prioritas: daftar lokal → negara dari Google Places → heuristik nama
    country: resolved?.country ?? googleCountry ?? guessCountry(text),
  };
}

