export function getProfile(cityName: string): DestinationProfile {
  const hit = byCity.get(cityName);
  if (hit) return hit;
  return buildSpecificProfile(cityName, "");
}

/**
 * Bangun profil spesifik untuk kota yang tidak ada di daftar — dipakai juga
 * untuk hasil Google Places (nama kanonik + negara + foto Google bila ada).
 * Tetap memakai atraksi/makanan simulasi realistis, tetapi dikaitkan dengan
 * nama & negara spesifik, bukan profil generik yang identik untuk semua kota.
 */
export function buildSpecificProfile(
  cityName: string,
  country: string,
  photoUrls?: string[],
): DestinationProfile {
  const inIndonesia = country === "Indonesia" || country === "";
  const region = inIndonesia ? "Indonesia" : country;
  const attractions: Attraction[] = GENERIC_ATTRACTIONS.map((a, i) => ({
    ...a,
    name:
      i === 0
        ? `Landmark utama ${cityName}`
        : i === 7 && !inIndonesia
          ? `Wisata alam sekitar ${cityName}`
          : a.name,
    ticket: inIndonesia ? [0, 25000, 0, 0, 0, 50000, 10000, 100000][i] : [0, 75000, 0, 0, 0, 120000, 50000, 200000][i],
  }));
  return {
    city: cityName,
    tagline: region ? `Jelajahi sisi terbaik ${cityName}, ${region}` : `Jelajahi sisi terbaik ${cityName}`,
    attractions,
    foods: inIndonesia
      ? [
          { name: "Hidangan khas lokal", priceRange: "Rp30.000–70.000/porsi" },
          { name: "Street food favorit warga", priceRange: "Rp15.000–40.000/porsi" },
          { name: "Dessert & kopi lokal", priceRange: "Rp20.000–50.000/porsi" },
        ]
      : [
          { name: "Restoran lokal populer", priceRange: "Rp60.000–150.000/porsi" },
          { name: "Street food & food court", priceRange: "Rp35.000–90.000/porsi" },
          { name: "Kafe & dessert lokal", priceRange: "Rp45.000–120.000/porsi" },
        ],
    photos: getProfilePhotos(cityName, photoUrls),
    transportNote:
      "Kombinasikan transportasi publik lokal, ojek/taksi online, dan jalan kaki di pusat kota.",
  };
}

function getProfilePhotos(
  cityName: string,
  photoUrls?: string[],
): { url: string; alt: string }[] {
  if (photoUrls && photoUrls.length > 0) {
    const list = photoUrls.slice(0, 3);
    while (list.length < 3) list.push(list[list.length - 1]);
    return list.map((url, i) => ({ url, alt: `${cityName} — foto ${i + 1} (Google Places)` }));
  }
  const h = hash(cityName);
  const ids = GENERIC_PHOTO_POOL[h % GENERIC_PHOTO_POOL.length];
  return [
    { url: unsplash(ids[0]), alt: `${cityName} — pemandangan 1` },
    { url: unsplash(ids[1]), alt: `${cityName} — pemandangan 2` },
    { url: unsplash(ids[2]), alt: `${cityName} — pemandangan 3` },
  ];
}

