function profileFor(name: string, country: string): DestinationProfile {
  const profile = getProfile(name);
  if (profile.city !== name) return profile; // hit dari daftar lokal
  const enriched = getEnriched(name);
  return buildSpecificProfile(name, country, enriched?.photoUrls);
}

