    profile: profileFor(input.destination, input.destinationCountry),
  };
  if (input.route && input.route.length > 1) {
    plan.profiles = input.route.map((r) => profileFor(r.name, r.country));
    plan.allocations = allocateDays(input.days, input.route.length);
  }
  return plan;
}

