   804	 * dihitung sebagai hari transit (bukan hari eksplorasi).
   805	 */
   806	export function allocateDays(totalDays: number, cityCount: number): number[] {
   807	  const transit = Math.max(0, cityCount - 1);
   808	  const explore = Math.max(cityCount, totalDays - transit);
   809	  const base = Math.floor(explore / cityCount);
   810	  const rem = explore - base * cityCount;
   811	  const order = [0, cityCount - 1, ...Array.from({ length: cityCount - 2 }, (_, i) => i + 1)];
   812	  const result = Array.from({ length: cityCount }, () => base);
   813	  for (let i = 0; i < rem; i++) result[order[i % order.length]]++;
   814	  return result;
   815	}
