/** Estimasi opsi transportasi sekali jalan untuk satu leg rute. */
export function legTransports(
  fromName: string,
  fromCountry: string,
  toName: string,
  toCountry: string,
): LegTransport[] {
  const a = normCity(fromName);
  const b = normCity(toName);
  for (const [x, y, opts] of PAIR_TRANSPORTS) {
    if ((a === x && b === y) || (a === y && b === x)) return opts;
  }
  if (fromCountry === toCountry && fromCountry === "Indonesia") {
    const band = getBand(toName, toCountry, fromName);
    if (band === "domestik-dekat") {
      return [
        { label: "Kereta / travel antar kota", price: [100_000, 300_000] },
        { label: "Pesawat domestik", price: [500_000, 1_100_000] },
      ];
    }
    return [{ label: "Pesawat domestik", price: [450_000, 1_800_000] }];
  }
  if (fromCountry === toCountry) {
    return [
      { label: "Kereta / bus antar kota", price: [200_000, 700_000] },
      { label: "Pesawat domestik", price: [600_000, 2_000_000] },
    ];
  }
  return [{ label: "Pesawat (estimasi OTA)", price: [800_000, 3_500_000] }];
}

